#include <bits/stdc++.h>
using namespace std;
string mul(const string&a, const string&b){
    int n=a.size(), m=b.size();
    vector<int> res(n+m, 0);
    for(int i=n-1;i>=0;i--){
        for(int j=m-1;j>=0;j--){
            int p1=i+j, p2=i+j+1;
            int sum = (a[i]-'0')*(b[j]-'0') + res[p2];
            res[p2] = sum % 10;
            res[p1] += sum / 10;
        }
    }
    string s;
    for(int d : res) s += char('0'+d);
    size_t start = s.find_first_not_of('0');
    if(start==string::npos) return "0";
    return s.substr(start);
}
int main(){
    string a,b;
    while(cin>>a>>b) cout << mul(a,b) << "\n";
}

